// Run from cmd/collections-check inside the pinned Ordarr source checkout so
// collection validation uses the application's actual import implementation.
package main
import("fmt";"io";"io/fs";"os";"path/filepath";"strings";"github.com/trentnbauer/Ordarr/internal/portable")
func main(){if len(os.Args)!=2{fmt.Fprintln(os.Stderr,"usage: collections-check COLLECTIONS_DIRECTORY | --self-test");os.Exit(2)};if os.Args[1]=="--self-test"{selfTest();return};root,err:=filepath.Abs(os.Args[1]);if err!=nil{panic(err)};count,total,failed:=0,0,false;ids:=map[string]string{};err=filepath.WalkDir(root,func(path string,entry fs.DirEntry,walkErr error)error{if walkErr!=nil{return walkErr};if entry.IsDir(){if path!=root&&strings.HasPrefix(entry.Name(),"."){return filepath.SkipDir};return nil};ext:=strings.ToLower(filepath.Ext(path));if ext!=".yaml"&&ext!=".yml"&&ext!=".json"{return nil};relative,_:=filepath.Rel(root,path);count++;fail:=func(message string){failed=true;escape:=strings.NewReplacer("%","%25","\r","%0D","\n","%0A",",","%2C",":","%3A");fmt.Printf("::error file=%s::%s\n",escape.Replace(filepath.ToSlash(relative)),escape.Replace(message))};if count>500{return fmt.Errorf("at most 500 collection files are permitted")};if !entry.Type().IsRegular(){fail("Collection files must be regular files, not links.");return nil};f,err:=os.Open(path);if err!=nil{return err};data,err:=io.ReadAll(io.LimitReader(f,portable.MaxBytes+1));f.Close();if err!=nil{return err};total+=len(data);if total>10<<20{return fmt.Errorf("total collection bytes exceed 10 MiB")};d,err:=portable.Decode(data);if err!=nil{fail(err.Error());return nil};if d.ID!=""{if previous,exists:=ids[d.ID];exists{fail(fmt.Sprintf("Collection id %q also appears in %q",d.ID,previous));return nil};ids[d.ID]=relative};c,err:=d.Collection();if err!=nil{fail(err.Error());return nil};fmt.Printf("PASS %q: %d ordered entries\n",relative,len(c.Entries));return nil});if err!=nil{fmt.Fprintln(os.Stderr,err);failed=true};if count==0{fmt.Fprintln(os.Stderr,"No collection YAML/JSON files were found.");failed=true};if failed{os.Exit(1)};fmt.Printf("Validated %d collection file(s) with Ordarr's import parser.\n",count)}
func selfTest(){valid:=`{"version":1,"title":"Example","entries":[{"id":"movie","kind":"movie","title":"Movie","provider":"tmdb","external_id":"1"}]}`;if _,err:=portable.Decode([]byte(valid));err!=nil{panic(err)};cases:=[]string{strings.Replace(valid,`"version":1`,`"version":2`,1),strings.Replace(valid,`"tmdb"`,`"unknown"`,1),strings.Replace(valid,`"external_id":"1"`,`"external_id":"bad"`,1),strings.Replace(valid,`"id":"movie"`,`"id":"has spaces"`,1),valid+"\n---\nversion: 1",strings.Repeat("x",portable.MaxBytes+1),`{"version":1,"title":"Duplicate","entries":[{"id":"same","kind":"movie","title":"A","provider":"tmdb","external_id":"1"},{"id":"same","kind":"movie","title":"B","provider":"tmdb","external_id":"2"}]}`};for i,data:=range cases{if _,err:=portable.Decode([]byte(data));err==nil{panic(fmt.Sprintf("invalid fixture %d was accepted",i))}};fmt.Println("PASS validator rejects malformed schema, providers, IDs, duplicates, multiple documents and oversized files.")}
